import json,sys
from pathlib import Path
from pyalamode.migration import write_baseline,MigrationError
calls=[]
def bad():
 calls.append(1)
 return True
root=Path(sys.argv[1]);state=json.loads(Path(sys.argv[2]).read_bytes())
try:write_baseline(root,state,owner="independent M13 review",rationale="malformed publication callback",prepublish=bad)
except MigrationError as e:print(json.dumps({"writer_error":type(e).__name__,"callback_calls":len(calls),"saved":(root/".pyalamode/baseline.json").exists()},sort_keys=True))
else:raise AssertionError("malformed callback accepted")

