HERE=Path(__file__).resolve().parent
CASE_SHA='475d229e8dc751175427f627c05ffdf38e3972b47f3476d49c327ea9b7e6f039'
CHECKER='characterized-tasks-13.0'
OPERATION='scalar-tuple-call-collection-record-boundary-effect-domain-failure-standard-integration-encoding-distribution-builder-task-ops-13'
LIFETIME='fresh callback invocation; invalidated on every exit; no alias, retention or transfer'
FINALIZATION='automatic exact Vector result after None; construction failure publishes no result'
SOURCE_EXCLUDES={'.git','.venv','__pycache__','.pyalamode-cache','.pyalamode','build','dist','node_modules','.DS_Store'}
CONTROLLER_EXCLUDES={'runs','prior','qa-raw','qa-raw-02','qa-raw-03','generation-raw-02','generation-raw-03','correction-03.diff','__pycache__','preparation-qa.json','preparation-qa-02.json','preparation-qa-03.json','preparation-intent.json','preparation-prior','source-map.json','planned-execution.json','preparation-map.json','preparation-receipt.json'}

def digest(raw):return hashlib.sha256(raw).hexdigest()
def canonical(value):return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()
