    path=Path(path)
    if not path.exists():return {'exists':False,'sha256':None,'size':None}
    raw=path.read_bytes();return {'exists':True,'sha256':digest(raw),'size':len(raw)}
def inventory(root,excluded=()):
    """Discover the whole finite path set again, including additions/deletions."""
    root=Path(root);result={};excluded=set(excluded)
    for directory,children,files in os.walk(root,followlinks=False):
        children[:]=sorted(n for n in children if n not in excluded)
        for name in sorted(files):
            if name in excluded:continue
            p=Path(directory)/name;key=str(p.relative_to(root))
            if p.is_symlink():result[key]={'kind':'symlink','target':os.readlink(p)}
            elif p.is_file():result[key]={'kind':'file',**receipt(p)}
            else:result[key]={'kind':'special'}
        for name in children:
            p=Path(directory)/name
            if p.is_symlink():result[str(p.relative_to(root))]={'kind':'symlink','target':os.readlink(p)}
    return result
def authored(project,names):return {name:receipt(Path(project)/name) for name in sorted(names)}
def load_cases():
    raw=(HERE/'cases.json').read_bytes()
    if digest(raw)!=CASE_SHA:raise AssertionError('approved case manifest changed')
